const getFilteredResults = async () => {
  const query = window.location.search ? window.location.search : '?';
  try {
    const res = await axios({
      method: 'GET',
      url: `/api/v1/tasks${query}&limit=1000`,
    });
    if (res.data.status === 'success') {
      const result = res.data.tasks.map((task) => [
        task.user.name,
        task.carModel,
        task.taskStatus,
        task.totalCost,
        new Date(task.createdAt).toLocaleDateString('en-US', {
          month: 'short',
          day: '2-digit',
          year: 'numeric',
        }),
      ]);
      return result;
    } else {
      return showAlert('error', res.data.message);
    }
  } catch (err) {
    return showAlert('error', err);
  }
};

export const generatePDF = async () => {
  const filteredResults = await getFilteredResults();
  const totalSum = filteredResults.reduce((acc, curr) => acc + curr[3], 0);
  const totalAmountTasks = filteredResults.length;
  const from =
    filteredResults[filteredResults.length - 1][
      filteredResults[filteredResults.length - 1].length - 1
    ];
  const to = filteredResults[0][filteredResults[0].length - 1];

  const docDefinition = {
    content: [
      { text: `Period: ${from} t/m ${to}`, style: 'subheader' },
      `Submitted tasks: ${totalAmountTasks}`,

      {
        layout: 'lightHorizontalLines',
        style: 'table',
        table: {
          headerRows: 1,
          widths: ['*', 'auto', 'auto', 50, 75],

          body: [
            ['Customer', 'Vehicle Model', 'Status', 'Cost', 'Date'],
            ...filteredResults,
            [
              { text: 'TOTAL', bold: true },
              '',
              '',
              { text: totalSum, bold: true },
              '',
            ],
          ],
        },
      },
    ],
    documentTitle: `summary${from}${to}.pdf`,
    styles: {
      header: {
        fontSize: 18,
        bold: true,
        margin: [0, 0, 0, 10],
      },
      subheader: {
        fontSize: 16,
        bold: true,
        margin: [0, 10, 0, 5],
      },
      table: {
        margin: [0, 5, 10, 15],
      },
      tableHeader: {
        bold: true,
        fontSize: 13,
        color: 'black',
      },
    },
  };
  pdfMake.createPdf(docDefinition).download();
};

